/bin/bash -lc "python3 - <<'PY'
import ast
from pathlib import Path
import subprocess
path = 'local/bin/pr_merge.py'
current = ast.parse(Path(path).read_text())
parents = {ref: ast.parse(subprocess.check_output(['git', 'show', f'{ref}:{path}'], text=True))
           for ref in ('HEAD', 'MERGE_HEAD')}
def functions(tree):
    return {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef)}
now = functions(current)
for name in ('head_is_fresh', '_base_advance_is_tolerated', '_is_tolerated_telemetry_change',
             '_is_tolerated_telemetry_path'):
    assert ast.dump(now[name]) == ast.dump(functions(parents['MERGE_HEAD'])[name]), name
for name in ('check_ci', 'check_review', 'check_fix_gates', 'check_dependencies', 'run_merge',
             'post_merge', 'remove_branch_and_worktree'):
    assert ast.dump(now[name]) == ast.dump(functions(parents['HEAD'])[name]), name
for tree in (current, parents['HEAD']):
    branch = next(node for node in ast.walk(functions(tree)['run_gate'])
                  if isinstance(node, ast.If) and ast.unparse(node.test) == 'integration_base is not None')
    if tree is current:
        frozen = ast.dump(ast.Module(body=branch.body, type_ignores=[]))
    else:
        assert frozen == ast.dump(ast.Module(body=branch.body, type_ignores=[]))
print('Unchanged: incoming freshness helpers, train frozen-base body, member gates, merge/publication/cleanup')
PY"

